export function snackIcon(id) {
  const s = SNACKS[id];
  const art = SNACK_ART[id];
  if (art) {
    // style-coloured ring, light disc, full-colour food
    return `<svg class="snack-ic" viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="16" r="14.5" fill="${s.color}" stroke="#1a1420" stroke-width="2"/><circle cx="16" cy="16" r="11.6" fill="#fff8ee"/><g transform="translate(5.2 5.2) scale(.675)" stroke="${INK}" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round">${art}</g></svg>`;
  }
  // light badges get a dark icon, dark badges a white one
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(s.color.slice(i, i + 2), 16));
  const ink = 0.299 * r + 0.587 * g + 0.114 * b > 160 ? INK : '#fff';
  return `<svg class="snack-ic" viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="16" r="14" fill="${s.color}" stroke="#1a1420" stroke-width="2.2"/><g transform="translate(6.4 6.4) scale(.6)" color="${ink}">${ICONS[s.icon] || ''}</g></svg>`;
}

export function icon(name, cls = '') {
  return `<svg class="${cls}" viewBox="0 0 32 32" aria-hidden="true">${ICONS[name] || ''}</svg>`;
}

// Jenny + enemies are drawn in the chibi vector style (see chibi.js).
export function jennySVG(opts = {}) { return jennyChibi(opts.outfit || wornOutfit('jenny'), opts); }
export function enemySVG(art, color) { return enemyChibi(art, color); }
// The playable character's art.
export function heroSVG(character, opts = {}) {
  if (character === 'toni') return toniChibi(opts.outfit || wornOutfit('toni'), opts);
  return jennySVG(opts);
}

